/* Medição acumulada por item do orçamento; grava somente os incrementos conferidos. */
(function(root){'use strict';const D=root.Obras,clone=D.clone,h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n),qty=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:6}).format(n),id=()=>root.crypto?.randomUUID?.()||'MS-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),$=s=>document.querySelector(s);
function number(v){let text=String(v??'').trim().replace(/%$/,'').trim();if(!/^\d+(?:[.,]\d+)?(?:e[+-]?\d+)?$/i.test(text))throw Error('Informe número não negativo, como 10 ou 12,5.');let n=Number(text.replace(',','.'));if(!Number.isFinite(n))throw Error('Número inválido.');return n}
function rows(s,project){if(s.dataModel!==2||!s.projects.some(p=>p.id===project))throw Error('Selecione uma obra com orçamento no topo da página.');return s.budgetItems.filter(a=>a.project===project).map(item=>{let previous=D.sum(s.measurements.filter(m=>m.project===project&&m.activity===item.id&&m.status!=='Glosada'),m=>m.quantity),total=Number(item.quantity),percentage=total>0?previous/total*100:0;return {id:item.id,name:item.name,code:D.planningCode(item),stage:s.budgetStages.find(st=>st.id===item.stage)?.name||'',unit:item.unit,total,sale:Number(item.sale),previous,complete:total>0&&previous>=total-Math.max(1e-10,Math.abs(total)*1e-10),previousPercent:percentage,current:total>0?String(percentage):'0',mode:'percent',selected:false}})}
function calculate(row){if(!['percent','quantity'].includes(row.mode))throw Error('Escolha percentual ou quantidade acumulada.');if(!(row.total>0)||!Number.isFinite(row.total))throw Error('O item precisa ter quantidade orçada positiva.');if(row.mode==='quantity'&&String(row.current).includes('%'))throw Error('Use o modo Percentual para informar valores com %.');let n=number(row.current),current=row.mode==='percent'?row.total*n/100:n,tolerance=Math.max(1e-10,Math.abs(row.total)*1e-10);if(row.complete&&Math.abs(current-row.previous)>tolerance)throw Error('Item já medido em 100%. Corrija a medição anterior para alterar este saldo.');if(row.mode==='percent'&&n>100.00000001||current>row.total+tolerance)throw Error('Acumulado não pode superar 100% da quantidade orçada.');if(current<row.previous-tolerance)throw Error('Acumulado não pode ser menor que o já medido. Corrija os lançamentos anteriores na lista, se necessário.');current=Math.min(row.total,Math.max(row.previous,current));let delta=current-row.previous;if(Math.abs(delta)<=tolerance)delta=0;return {current,percent:current/row.total*100,delta,value:Math.round(delta*row.sale/row.total*100)/100,remaining:row.total-current}}
function saveBatch(state,project,meta,draft){let source=rows(state,project),numberId=String(meta.number||'').trim();if(!numberId)throw Error('Informe o número da medição.');if(!/^\d{4}-\d{2}-\d{2}$/.test(meta.date||'')||D.date(meta.date)?.toLocaleDateString('sv-SE')!==meta.date)throw Error('Informe uma data base válida.');if(state.measurements.some(m=>m.project===project&&String(m.number).trim().toLocaleLowerCase('pt-BR')===numberId.toLocaleLowerCase('pt-BR')))throw Error('Este número de medição já existe nesta obra. Use outro número para uma nova medição; edite os registros anteriores pela lista ou planilha.');if(!Array.isArray(draft))throw Error('Planilha inválida.');let seen=new Set(),changes=[];for(let input of draft){if(!input.selected)continue;if(seen.has(input.id))throw Error('Item repetido na planilha.');seen.add(input.id);let row=source.find(r=>r.id===input.id);if(!row)throw Error('Item não pertence ao orçamento desta obra.');let result;try{result=calculate({...row,mode:input.mode,current:input.current})}catch(e){throw Error(row.name+': '+e.message)}if(result.delta>0)changes.push({row,...result})}if(!changes.length)throw Error('Informe um aumento no acumulado de pelo menos um item selecionado.');let next=clone(state),batch=id();for(let change of changes){let record={id:id(),project,activity:change.row.id,number:numberId,date:meta.date,quantity:change.delta,status:'Preparada',submitted:'',approved:'',expected:'',evidence:'',note:String(meta.note||''),measurementType:meta.measurementType||'Medição',measurementSheetBatch:batch};next=D.saveRecord(next,'measurements',record)}next.history.unshift({id:id(),time:new Date().toISOString(),kind:'measurementSheet',record:batch,action:'Medição em planilha criada',before:null,after:{project,number:numberId,items:changes.length,total:changes.reduce((n,c)=>n+c.value,0)}});return next}
function releaseBatch(state,recordId,meta){let first=state.measurements.find(m=>m.id===recordId);if(!first)throw Error('Medição não encontrada.');for(let key of ['submitted','approved','expected'])if(!/^\d{4}-\d{2}-\d{2}$/.test(meta[key]||'')||D.date(meta[key])?.toLocaleDateString('sv-SE')!==meta[key])throw Error('Informe datas válidas de apresentação, aprovação e previsão de recebimento.');if(!String(meta.evidence||'').trim())throw Error('Informe a referência da aprovação / evidência.');let next=clone(state),group=state.measurements.filter(m=>m.project===first.project&&m.number===first.number);for(let m of group){next=D.saveRecord(next,'measurements',{...m,status:'Aprovada',submitted:meta.submitted,approved:meta.approved,expected:meta.expected,evidence:String(meta.evidence).trim()})}return next}
function openRelease(recordId){snapshot=clone(api.getState());let first=snapshot.measurements.find(m=>m.id===recordId);if(!first)throw Error('Medição não encontrada.');let group=snapshot.measurements.filter(m=>m.project===first.project&&m.number===first.number);if(group.every(m=>m.status==='Aprovada'))throw Error('Esta medição já está liberada.');pending=false;$('#readerTitle').textContent='Liberar medição '+first.number;$('#readerContent').innerHTML='<form id="measurementReleaseForm" class="reader-page measurement-release-editor"><p>A liberação aprova os <strong>'+group.length+' itens</strong> desta medição e atualiza o líquido em Contas a receber, conforme a retenção contratual. Nenhum recebimento é registrado aqui.</p>'+(group.some(m=>m.status==='Glosada')?'<p class="notice">Esta medição contém itens glosados. Ao liberar, eles também serão aprovados, respeitando o saldo disponível do orçamento.</p>':'')+'<label>Data de apresentação<input id="measurementReleaseSubmitted" type="date" required value="'+h(first.submitted||D.today())+'"></label><label>Data de aprovação<input id="measurementReleaseApproved" type="date" required value="'+D.today()+'"></label><label>Previsão de recebimento<input id="measurementReleaseExpected" type="date" required value="'+h(first.expected||'')+'"></label><label>Aprovação / referência da evidência<textarea id="measurementReleaseEvidence" required>'+h(first.evidence||'')+'</textarea></label><p id="measurementReleaseError" role="alert" class="red-text"></p><button id="measurementReleaseSave" type="submit" class="button primary">Liberar medição inteira</button></form>';$('#reader').showModal();$('#measurementReleaseForm').onsubmit=async e=>{e.preventDefault();if(pending)return;try{if(JSON.stringify(api.getState())!==JSON.stringify(snapshot))throw Error('Os dados mudaram. Reabra a medição antes de liberar.');let next=releaseBatch(snapshot,recordId,{submitted:$('#measurementReleaseSubmitted').value,approved:$('#measurementReleaseApproved').value,expected:$('#measurementReleaseExpected').value,evidence:$('#measurementReleaseEvidence').value});pending=true;$('#measurementReleaseSave').disabled=true;if(await api.save(next)===false)throw Error('O servidor não confirmou a liberação. Atualize os dados antes de tentar novamente.');pending=false;$('#reader').close();api.render();api.toast('Medição inteira liberada e Contas a receber atualizado.')}catch(err){pending=false;$('#measurementReleaseSave').disabled=false;$('#measurementReleaseError').textContent=err.message}}}

let api,snapshot,draft=[],editingProject='',pending=false;
function isDirty(){return !!$('#reader')?.open&&(!!$('#readerContent .measurement-sheet-editor')||!!$('#readerContent .measurement-release-editor'))}
function suggestedNumber(s,p){let used=new Set(s.measurements.filter(m=>m.project===p).map(m=>String(m.number).trim().toUpperCase()));for(let i=1;i<100000;i++){let value='MED-'+String(i).padStart(3,'0');if(!used.has(value))return value}return ''}
function open(){editingProject=api.getProject();snapshot=clone(api.getState());draft=rows(snapshot,editingProject);if(!draft.length)throw Error('Esta obra ainda não tem itens no orçamento. Cadastre ou importe o orçamento primeiro.');pending=false;$('#readerTitle').textContent='Nova medição em planilha';$('#readerContent').innerHTML='<div class="reader-page measurement-sheet-editor"><div class="notice neutral">Informe o <strong>acumulado atual</strong>, em percentual ou quantidade. O sistema registra somente o aumento sobre o já lançado, incluindo medições preparadas e excluindo glosas. Exemplo: anterior 10%, atual 25%, nesta medição 15%. Uma medição reúne vários itens sob o mesmo número. Os itens já medidos em 100% ficam visíveis e bloqueados nas próximas medições. Os itens sem aumento não são lançados. Para a entrada, escolha o tipo Entrada e distribua seu valor nos itens do orçamento (por exemplo, 20% de cada item). Ela já abate o saldo das próximas medições. A retenção usa o percentual configurado na obra.</div><form id="measurementSheetForm"><div class="measurement-sheet-meta"><label>Número da nova medição<input id="measurementSheetNumber" required value="'+h(suggestedNumber(snapshot,editingProject))+'"></label><label>Data base<input type="date" id="measurementSheetDate" required value="'+D.today()+'"></label><label>Tipo<select id="measurementSheetType"><option>Medição</option><option>Entrada</option></select></label><label>Observações<input id="measurementSheetNote" value=""></label></div><p class="section-note">Uma linha por item do orçamento. Digitar um aumento seleciona a linha; desmarque para não incluir. Você pode colar uma coluna do Excel em Acumulado atual. Todos os itens serão salvos como Preparada, para conferência antes de apresentar.</p><div class="measurement-sheet-meta"><label>Acumulado para todos os itens (%)<input id="measurementSheetFill" type="number" min="0" max="100" step="any" placeholder="Ex.: 20 para entrada de 20%"></label><button type="button" class="button secondary" id="measurementSheetFillApply">Aplicar em todos</button></div><p class="section-note">Aplica a todos os itens, inclusive os ocultos pela pesquisa, sem reduzir o acumulado já lançado. Confira o total antes de salvar.</p><label>Pesquisar item, código ou etapa<input id="measurementSheetSearch" type="search" placeholder="Filtrar linhas do orçamento"></label><div class="table-wrap measurement-sheet-wrap"><table class="measurement-sheet-table"><thead><tr><th>Incluir</th><th>Item / etapa do orçamento</th><th>Orçado</th><th>Medido anteriormente</th><th>Preencher em</th><th>Acumulado atual</th><th>Nesta medição</th><th>Valor desta medição</th><th>Saldo a medir</th></tr></thead><tbody>'+draft.map((r,i)=>'<tr data-ms-row="'+i+'"><td><input type="checkbox" data-ms-select="'+i+'" aria-label="Incluir '+h(r.name)+'" '+(r.total>0&&!r.complete?'':'disabled')+'></td><td class="wrap"><strong>'+h([r.code,r.name].filter(Boolean).join(' · '))+'</strong><div class="source-line">'+h(r.stage)+'</div>'+(r.complete?'<small class="pill">100% medido · bloqueado</small>':'')+'</td><td>'+qty(r.total)+' '+h(r.unit)+'<br>'+money(r.sale)+'</td><td>'+qty(r.previousPercent)+'%<br>'+qty(r.previous)+' '+h(r.unit)+'</td><td><select data-ms-mode="'+i+'" aria-label="Modo de preenchimento de '+h(r.name)+'" '+(r.total>0&&!r.complete?'':'disabled')+'><option value="percent">Percentual (%)</option><option value="quantity">Quantidade ('+h(r.unit)+')</option></select></td><td><input data-ms-current="'+i+'" inputmode="decimal" value="'+h(r.current)+'" aria-label="Acumulado atual de '+h(r.name)+'" '+(r.total>0&&!r.complete?'':'disabled')+'><button type="button" class="button secondary" data-ms-full="'+i+'" aria-label="Medir 100% de '+h(r.name)+'" '+(r.total>0&&!r.complete?'':'disabled')+'>Medir 100%</button></td><td data-ms-delta="'+i+'"></td><td data-ms-value="'+i+'"></td><td data-ms-remaining="'+i+'"></td></tr>').join('')+'</tbody></table></div><p id="measurementSheetSummary" class="notice neutral" aria-live="polite"></p><p id="measurementSheetError" class="red-text" role="alert"></p><div class="measurement-sheet-actions"><button class="button primary" id="measurementSheetSave" type="submit">Salvar nova medição como preparada</button></div></form></div>';$('#reader').showModal();$('#measurementSheetSearch').oninput=()=>{let norm=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),term=norm($('#measurementSheetSearch').value);for(let el of document.querySelectorAll('[data-ms-row]')){let r=draft[el.dataset.msRow];el.hidden=!norm([r.code,r.name,r.stage].join(' ')).includes(term)}};for(let el of document.querySelectorAll('[data-ms-select]'))el.onchange=()=>{draft[el.dataset.msSelect].selected=el.checked;update()};for(let el of document.querySelectorAll('[data-ms-current]')){el.oninput=()=>{let row=draft[el.dataset.msCurrent];row.current=el.value;try{row.selected=calculate(row).delta>0}catch{row.selected=true}let check=$('[data-ms-select="'+el.dataset.msCurrent+'"]');if(check)check.checked=row.selected;update()};el.onpaste=e=>{let text=e.clipboardData?.getData('text/plain');if(!text||!/[\n\t]/.test(text))return;e.preventDefault();let values=text.trim().split(/\r?\n/).map(line=>line.split('\t'));if(values.some(row=>row.length!==1)){api.toast('Cole apenas uma coluna de acumulados por vez.');return}let start=Number(el.dataset.msCurrent);if(start+values.length>draft.length){api.toast('A colagem ultrapassa os itens do orçamento.');return}for(let [offset,[value]]of values.entries()){let index=start+offset,cell=$('[data-ms-current="'+index+'"]');if(cell&&!cell.disabled){cell.value=value;cell.oninput()}}}}for(let el of document.querySelectorAll('[data-ms-full]'))el.onclick=()=>{let i=Number(el.dataset.msFull),row=draft[i];if(pending||!row||row.complete||!(row.total>0))return;row.mode='percent';row.current='100';row.selected=calculate(row).delta>0;$('[data-ms-mode="'+i+'"]').value='percent';$('[data-ms-current="'+i+'"]').value='100';$('[data-ms-select="'+i+'"]').checked=row.selected;update()};for(let el of document.querySelectorAll('[data-ms-mode]'))el.onchange=()=>{let i=el.dataset.msMode,row=draft[i];try{let result=calculate(row);row.mode=el.value;row.current=String(row.mode==='percent'?result.percent:result.current)}catch{row.mode=el.value;row.current=String(row.mode==='percent'?row.previousPercent:row.previous)}$('[data-ms-current="'+i+'"]').value=row.current;update()};$('#measurementSheetFillApply').onclick=()=>{try{let n=number($('#measurementSheetFill').value);if(n>100)throw Error('O acumulado deve ficar entre 0 e 100%.');for(let [i,r]of draft.entries()){if(!(r.total>0)||r.complete)continue;r.mode='percent';r.current=String(Math.max(n,r.previousPercent));r.selected=calculate(r).delta>0;$('[data-ms-mode="'+i+'"]').value='percent';$('[data-ms-current="'+i+'"]').value=r.current;$('[data-ms-select="'+i+'"]').checked=r.selected}update()}catch(e){api.toast(e.message)}};$('#measurementSheetForm').onsubmit=async e=>{e.preventDefault();if(pending)return;try{if(JSON.stringify(api.getState())!==JSON.stringify(snapshot))throw Error('Os dados mudaram. Reabra a planilha para atualizar os acumulados antes de salvar.');let next=saveBatch(snapshot,editingProject,{number:$('#measurementSheetNumber').value,date:$('#measurementSheetDate').value,note:$('#measurementSheetNote').value,measurementType:$('#measurementSheetType').value},draft);pending=true;for(let el of document.querySelectorAll('.measurement-sheet-editor input,.measurement-sheet-editor select,.measurement-sheet-editor button'))el.disabled=true;let result=await api.save(next);if(result===false)throw Error('O servidor não confirmou a medição. Atualize os dados antes de tentar novamente.');pending=false;$('#reader').close();api.render();api.toast('Nova medição salva apenas com os incrementos informados.')}catch(e){pending=false;$('#measurementSheetError').textContent=e.message;for(let el of document.querySelectorAll('.measurement-sheet-editor input,.measurement-sheet-editor select,.measurement-sheet-editor button'))el.disabled=false;for(let [i,r]of draft.entries())if(!(r.total>0)||r.complete)for(let key of ['select','mode','current','full']){let el=$('[data-ms-'+key+'="'+i+'"]');if(el)el.disabled=true}update()}};update()}
function update(){let total=0,count=0,errors=0;draft.forEach((r,i)=>{let delta=$('[data-ms-delta="'+i+'"]'),value=$('[data-ms-value="'+i+'"]'),remaining=$('[data-ms-remaining="'+i+'"]');try{let result=calculate(r);delta.textContent=qty(result.delta/r.total*100)+'% · '+qty(result.delta)+' '+r.unit;value.textContent=money(result.value);remaining.textContent=qty(result.remaining)+' '+r.unit;if(r.selected&&result.delta>0){count++;total+=Math.round(result.value*100)}delta.classList.remove('red-text')}catch(e){delta.textContent=e.message;delta.classList.add('red-text');value.textContent='—';remaining.textContent='—';if(r.selected)errors++}});$('#measurementSheetSummary').textContent=count+' itens com incremento selecionados · Total desta medição: '+money(total/100)+(errors?' · '+errors+' itens precisam de correção.':'');$('#measurementSheetSave').disabled=pending||!count||!!errors}
root.EngefexMeasurementSheet={rows,calculate,saveBatch,releaseBatch,number,isDirty,busy:()=>pending,handle(action){if(action!=='measurement-sheet'&&!action?.startsWith('measurement-release:'))return false;try{if(action.startsWith('measurement-release:'))openRelease(action.slice(20));else open()}catch(e){api.toast(e.message)}return true},init(bridge){api=bridge}};
})(typeof window==='undefined'?globalThis:window);
